<?php if ($detail !== null): ?><section class="card card-body extension-panel"><h2 class="card-title">발송 상세</h2><dl><dt>템플릿</dt><dd><?= $this->e($detail['template_name']) ?></dd><dt>요청 시각</dt><dd><?= $this->e($time($detail['created_at'])) ?></dd><dt>수신번호</dt><dd><?= $this->e($detail['phone_mask'] ?: '보관 만료') ?></dd><dt>접수 상태</dt><dd><?= $this->e($status_labels[$detail['submission']] ?? $detail['submission']) ?></dd><dt>도달 상태</dt><dd><?= $this->e($status_labels[$detail['delivery']] ?? $detail['delivery']) ?></dd></dl>
<?php if ($detail['snapshot'] !== null): ?><h3 class="form-section-title">발송 당시 본문</h3><pre><?= $this->e($detail['snapshot']['content']['at']['message']) ?></pre><?php else: ?><p>개인정보 보관 기간이 지나 발송 내용을 삭제했습니다.</p><?php endif ?>
