<h3 class="form-section-title">도달 결과</h3><?php if ($detail['receipts'] === []): ?><p>아직 수신된 결과가 없습니다.</p><?php endif ?><?php foreach ($detail['receipts'] as $receipt): ?><p><?= $this->e($time($receipt['received_at'])) ?> · <?= $this->e($receipt['media']) ?> · 코드 <?= $this->e($receipt['result_code']) ?> · <?= $this->e($receipt['result_description']) ?></p><?php endforeach ?>
